---@class CommonTipsBoard
local CommonTipsBoard = Class('CommonTipsBoard')

function CommonTipsBoard:__init()
    self.__closing = false
    ---@type UnityEngine.RectTransform
    self._cacheRectTrans = nil
    ---@type Engine.Lib.BehaviourAction
    self._behaviourAction = nil
    ---@type UnityEngine.Coroutine
    self._co = nil               --计算位置时需要等一帧的协程
end

function CommonTipsBoard:__delete()
    self._behaviourAction = nil
    self.__closing = false
    self._cacheRectTrans = nil
    self._co = nil 
end

function CommonTipsBoard:Awake()
    self._isInGuiding = GuideUtils.IsInGuiding()

    self.eventDestoryCommonTipsBord = Events.AddListener('DestoryCommonTipsBord', Bind(self, self.DestroySelf))
    self._cacheRectTrans = self.Bg:GetComponent(_RectTransform)
	self:Init()
end

function CommonTipsBoard:Start()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function CommonTipsBoard:Update()
    if not self.__closing then
        if Utils.TouchCount() > 0 then
            local positionV = Utils.GetInputDownPos()
            local position = Vector2.New(positionV.x, positionV.y)
            if position ~= Vector2.zero then
                local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self._cacheRectTrans, position,
                        UIModule.RootCanvas.canvas.worldCamera)
                if not isInRect and KCookie.Get(Constants.UICacheDataKeys.SetTipsBoardClickCloseFlag) == nil then
                    ---不在区域中
                    self:DestroySelf()
                end
            end
        end
        if Input.GetKeyUp(KeyCode.Escape) then
            self:DestroySelf()
        end
    end
end

function CommonTipsBoard:OnDestroy()
    if self.eventDestoryCommonTipsBord then
        Events.RemoveListener('DestoryCommonTipsBord', self.eventDestoryCommonTipsBord)
    end
    self.eventDestoryCommonTipsBord = nil
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
    if not isNull(self) then
        if self._co then
            CoStop(self._co)
            self._co = nil
        end
    end

    self.controller = nil --luabehaviour 中CSharp对象 self:Delete()
end
