---技能描述面板调整位置
---@param targetNodeGo UnityEngine.GameObject @ 目标节点
---@param isUpDown boolean @ 是否是计算上下位置
---@param isInTheCenter boolean @ 是否在targetNode中心位置显示
function CommonTipsBoard:FixBoardPosition(targetNode, isUpDown, isInTheCenter,isIgnoreDown)
    --layout太复杂 等一帧计算位置
    self._co = CoStart(function()
        coroutine.yield(Yielders.FixedUpdate)
        if isUpDown then
            self:FixUpDownPosition(targetNode,isIgnoreDown)
        else
            self:FixLeftRightPosition(targetNode, isInTheCenter)
        end
    end)
end 

--左右
---@param targetNodeGo UnityEngine.GameObject @ 目标节点
---@param isInTheCenter boolean @ 是否在targetNode中心位置显示(默认为true)
---@param isIgnoreDown boolean @是否忽略下面（强制显示在上面）
function CommonTipsBoard:FixLeftRightPosition(targetNode, isInTheCenter)
    isInTheCenter = isInTheCenter ~= false
    local bgRect = CfUtils.GetNodeRect(self.Bg)
    local arrowRect = self.Arrow and CfUtils.GetNodeRect(self.Arrow) or {width = 0, height = 0}
    local targetPivotX = isInTheCenter and 0.5 or 0
    --指针的坐标
    local pos = CfUtils.GetUITargetPos(targetNode, self.Arrow, nil, targetPivotX, 0.5, 1, 0.5)
    --先算左边
    local sparePos = Vector3(pos.x - bgRect.width * 0.5 - arrowRect.width * 0.5, pos.y, pos.z)

    local isInWidthScreen, _ = CfUtils.IsPosWidthInScreenRect(sparePos, bgRect.width * 0.5)
    --如果没超出屏幕
    if isInWidthScreen  then
        if self.Arrow then
            pos = Vector3(pos.x + 20, pos.y, pos.z)
            self.Arrow.anchoredPosition3D = pos
        end

        --背景的高度偏移矫正
        local isInHeightScreen, overflowNum = CfUtils.IsPosHighInScreenRect(sparePos, bgRect.height * 0.5)
        local bgPos = CfUtils.GetUITargetPos(targetNode, self.Bg, nil, targetPivotX, 0.5, 1, 0.5)
        --如果高度超出了屏幕
        if not isInHeightScreen then
            bgPos = Vector3(bgPos.x, bgPos.y + overflowNum, bgPos.z)
        end
        self.Bg.anchoredPosition3D = Vector3(bgPos.x - arrowRect.width + 15 + 20, bgPos.y)

    else
        targetPivotX = isInTheCenter and 0.5 or 1
        pos = CfUtils.GetUITargetPos(targetNode, self.Arrow, nil, targetPivotX, 0.5, 0, 0.5)
        if self.Arrow then
            self.Arrow.transform:Rotate(Vector3(0, 0, 180))
            pos = Vector3(pos.x - 20, pos.y, pos.z)
            self.Arrow.anchoredPosition3D = pos
        end
        sparePos = Vector3(pos.x + bgRect.width * 0.5 + arrowRect.width * 0.5, pos.y, pos.z)

        --背景的高度偏移矫正
        local isInHeightScreen, overflowNum = CfUtils.IsPosHighInScreenRect(sparePos, bgRect.height * 0.5)
        local bgPos = CfUtils.GetUITargetPos(targetNode, self.Bg, nil, targetPivotX, 0.5, 0, 0.5)
        --如果高度超出了屏幕
        if not isInHeightScreen then
            bgPos = Vector3(bgPos.x, bgPos.y + overflowNum, bgPos.z)
        end
        self.Bg.anchoredPosition3D = Vector3(bgPos.x + arrowRect.width - 15 - 20, bgPos.y)
    end
end

--上下
---@param targetNodeGo UnityEngine.GameObject @ 目标节点
function CommonTipsBoard:FixUpDownPosition(targetNode,isIgnoreDown)
    local bgRect = CfUtils.GetNodeRect(self.Bg)
    local arrowRect = self.Arrow and CfUtils.GetNodeRect(self.Arrow, true) or {width = 0, height = 0}

    --指针的坐标
    local pos = CfUtils.GetUITargetPos(targetNode, self.Arrow, nil, 0.5, 0, 0.5, 1, true)
    --先算下边
    local sparePos = Vector3(pos.x, pos.y - bgRect.height * 0.5 - arrowRect.width * 0.5, pos.z)

    local isInWidthScreen, _ = CfUtils.IsPosHighInScreenRect(sparePos, bgRect.height * 0.5)
    --如果没超出屏幕
    if isInWidthScreen and not isIgnoreDown then
        if self.Arrow then
            pos = Vector3(pos.x, pos.y + 20, pos.z)
            self.Arrow.anchoredPosition3D = pos
            self.Arrow.transform:Rotate(Vector3(0, 0, 90))
        end

        --背景的高度偏移矫正
        local isInHeightScreen, overflowNum = CfUtils.IsPosWidthInScreenRect(sparePos, bgRect.width * 0.5)
        local bgPos = CfUtils.GetUITargetPos(targetNode, self.Bg, nil, 0.5, 0, 0.5, 1)
        --如果高度超出了屏幕
        if not isInHeightScreen then
            bgPos = Vector3(bgPos.x + overflowNum, bgPos.y, bgPos.z)
        end
        self.Bg.anchoredPosition3D = Vector3(bgPos.x, bgPos.y - arrowRect.height + 13 + 20)

    else
        pos = CfUtils.GetUITargetPos(targetNode, self.Arrow, nil, 0.5, 1, 0.5, 0, true)
        sparePos = Vector3(pos.x, pos.y + bgRect.height * 0.5 + arrowRect.width * 0.5, pos.z)
        
        if self.Arrow then
            pos = Vector3(pos.x, pos.y - 19, pos.z)
            self.Arrow.anchoredPosition3D = pos
            self.Arrow.transform:Rotate(Vector3(0, 0, 270))
        end

        --背景的高度偏移矫正
        local isInHeightScreen, overflowNum = CfUtils.IsPosWidthInScreenRect(sparePos, bgRect.width * 0.5)
        local bgPos = CfUtils.GetUITargetPos(targetNode, self.Bg, nil, 0.5, 1, 0.5, 0)
        --如果高度超出了屏幕
        if not isInHeightScreen then
            bgPos = Vector3(bgPos.x + overflowNum, bgPos.y, bgPos.z)
        end

        self.Bg.anchoredPosition3D = Vector3(bgPos.x, bgPos.y + arrowRect.height - 13 - 20)
    end
end

---技能描述面板调整位置
---pivot是（0.5，0.5）
---@param targetNodeGo UnityEngine.GameObject @ 目标节点
function CommonTipsBoard:FixBoardPosition2(targetNode)
    -- 提示板自身的rect transform
    local selfRectTransform = self.controller:GetComponent(_RectTransform)

    -- 父节点
    local parentTransform = self.parentObject.transform

    selfRectTransform:SetParent(parentTransform)
    self.controller.gameObject.layer = self.parentObject.gameObject.layer
    -- 设置一些初始的transform
    selfRectTransform.localPosition = Vector3.zero;
    selfRectTransform.localScale = Vector3.one;
    selfRectTransform.localRotation = Quaternion.identity;
    selfRectTransform:SetWidth(self.Bg.rect.width);
    selfRectTransform:SetHeight(self.Bg.rect.height);

    if not KTool.IsNull(targetNode) then
        local targetRectTransform = targetNode:GetComponent(_RectTransform)
        if not KTool.IsNull(targetRectTransform) then

            -- 计算目标的bounds
            local targetBounds = RectTransformUtility.CalculateRelativeRectTransformBounds(targetRectTransform.parent, targetRectTransform)

            -- 计算修正后自己的相对坐标
            local targetLocalPosition = parentTransform:InverseTransformPoint(targetRectTransform.parent:TransformPoint(targetBounds.center))

            -- 计算当前屏幕边界
            local screenBounds = self:CalcScreenBounds()

            -- 计算自己的边界
            local selfBounds = self:CalcSelfBounds()

            ------------ x边界检测 ------------
            if targetLocalPosition.x + selfBounds.max.x > screenBounds.max.x - paddingX then
                -- 超右边界
                targetLocalPosition.x = screenBounds.max.x - paddingX - selfBounds.max.x
            elseif targetLocalPosition.x + selfBounds.min.x < screenBounds.min.x + paddingX then
                -- 超左边界
                targetLocalPosition.x = targetLocalPosition.x + selfBounds.size.x / 2
            end
            ------------ y边界检测 ------------
            -- y坐标默认上显示
            if targetLocalPosition.y + targetBounds.max.y + paddingY > screenBounds.max.y - selfBounds.size.y then
                -- 上面空间不够 向下显示
                local targetNodeBottom = targetLocalPosition.y - targetRectTransform.rect.height * targetRectTransform.pivot.y - paddingY
                targetLocalPosition.y = targetNodeBottom - self.Bg.rect.height / 2
            else
                -- 空间够 默认上显示
                local targetNodeTop = targetLocalPosition.y + targetRectTransform.rect.height * (1 - targetRectTransform.pivot.y) + paddingY
                targetLocalPosition.y = targetNodeTop + selfBounds.size.y / 2 - targetBounds.extents.y
            end
            ------------ y边界检测 ------------

            targetLocalPosition.z = 0
            selfRectTransform.localPosition = targetLocalPosition

            --selfRectTransform.anchoredPosition3D = Vector3.New(targetLocalPosition.x, targetLocalPosition.y, 0)

        end
    end
end

--- 计算屏幕的边界
---@return Bounds @ 屏幕边界的bounds
function CommonTipsBoard:CalcScreenBounds()
    local corners = spt.new_array(typeof(CS.UnityEngine.Vector3), 4)
    self.parentObject:GetComponent(_RectTransform):GetLocalCorners(corners)

    local center = Vector3.New(0, 0, 0)
    local size = Vector3.New(self.parentObject:GetComponent(_RectTransform).rect.width, self.parentObject:GetComponent(_RectTransform).rect.height, 0)
    for _, pos in array_pairs(corners) do
        center.x = center.x + pos.x
        center.y = center.y + pos.y
        center.z = center.x + pos.z
    end

    center.x = center.x * 0.5
    center.y = center.y * 0.5
    center.z = center.z * 0.5

    local screenBounds = Bounds.New(
            center,
            size
    )
    return screenBounds
end

--- 计算自己的边界
---@return Bounds @ 自己边界的bounds
function CommonTipsBoard:CalcSelfBounds()
    return RectTransformUtility.CalculateRelativeRectTransformBounds(
            self.parentObject.transform, self.Bg
    )
end

function CommonTipsBoard:FixBoardPosition3(targetNode, targetNodeOffset, showOnLeftRigth)
    local bgRect = CfUtils.GetNodeRect(self.Bg)
    local targetNodeRect = CfUtils.GetNodeRect(targetNode)

    -- 计算targetNode在UI坐标系里的坐标
    local cam = UIModule.RootCanvas.defaultCamera
    local topLayerRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenPoint = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(cam, targetNode.transform.position)
    local isSuccess, targetNodeUIPos = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, screenPoint, cam)
    -- 在目标中心位置的基础上加一个偏移，我们要让bg的锚点对齐到这个位置上
    local bgTargetPos = targetNodeUIPos + (targetNodeOffset or Vector2.zero)
    -- print("[计算] target pos", bgTargetPos)

    -- 计算bg锚点到bg中心位置的偏移
    local bgRT = self.Bg.transform:GetComponent(typeof(RectTransform)) or {}
    local bgOffsetX = (0.5 - bgRT.pivot.x) * bgRect.width
    local bgOffsetY = (0.5 - bgRT.pivot.y) * bgRect.height
    -- print("[计算] bg pivot offset", bgOffsetX, bgOffsetY)

    -- 计算bg的中心点
    local bgCenterPos = Vector2.New(bgTargetPos.x + bgOffsetX, bgTargetPos.y + bgOffsetY)
    -- print("[计算] bg center pos", bgCenterPos)

    -- 如果bg有一部分超出屏幕，需要自动调整位置
    if showOnLeftRigth then
        -- 如果bg是出现在目标节点的左右两侧，那么当高度不足时，只需要上下挪动，当宽度不足时，则需要放到目标节点的另一侧
        local newBgCenterPos = bgCenterPos

        -- 计算高度是否足够，不够的话，上下调整高度（这里不考虑高度完全不够的情况）
        local isHeightEnough, heightFlowNum = CfUtils.IsPosHighInScreenRect(newBgCenterPos, bgRect.height * 0.5)
        -- print("[计算] is height enough", isHeightEnough, heightFlowNum)
        local pos1 = newBgCenterPos    -- 这行只是一个缓存
        if not isHeightEnough then
            pos1 = Vector2.New(bgCenterPos.x, bgCenterPos.y + heightFlowNum)
            newBgCenterPos = pos1
            -- print("[计算] new bg center pos", newBgCenterPos)
        end

        -- 计算宽度是否足够，不够的话，尝试放到targetNode的另一边
        local isWidthEnough, widthFlowNum = CfUtils.IsPosWidthInScreenRect(newBgCenterPos, bgRect.width * 0.5)
        local pos2 = newBgCenterPos    -- 这行只是一个缓存
        if not isWidthEnough then
            -- 计算放到另一侧的话，bg的中心点坐标
            pos2 = Vector2.New(targetNodeUIPos.x - (newBgCenterPos.x - targetNodeUIPos.x), newBgCenterPos.y)
            newBgCenterPos = pos2
        end

        -- 放置到另一侧以后，再看看空间够不够
        local isWidthEnough2, widthFlowNum2 = CfUtils.IsPosWidthInScreenRect(newBgCenterPos, bgRect.width * 0.5)
        if not isWidthEnough2 then
            -- 如果两边都不够，那就选小的一边挪动一下位置
            if widthFlowNum < widthFlowNum2 then
                newBgCenterPos = Vector2.New(pos1.x + widthFlowNum, pos1.y)
            else
                newBgCenterPos = Vector2.New(pos2.x + widthFlowNum2, pos2.y)
            end
        end

        -- 再计算新的锚点目标坐标
        bgTargetPos = Vector2.New(newBgCenterPos.x - bgOffsetX, newBgCenterPos.y - bgOffsetY)
    else
        -- 如果bg是出现在目标节点的上下两侧，那么当宽度不足时，只需要左右挪动，当高度不足时，则需要放到目标节点的另一侧
        local newBgCenterPos = bgCenterPos
        local pos1 = newBgCenterPos
        local isWidthEnough, widthFlowNum = CfUtils.IsPosWidthInScreenRect(newBgCenterPos, bgRect.width * 0.5)
        if not isWidthEnough then
            pos1 = Vector2.New(bgCenterPos.x + widthFlowNum, bgCenterPos.y)
            newBgCenterPos = pos1
        end

        local isHeightEnough, heightFlowNum = CfUtils.IsPosHighInScreenRect(newBgCenterPos, bgRect.height * 0.5)
        local pos2 = newBgCenterPos
        if not isHeightEnough then
            pos2 = Vector2.New(newBgCenterPos.x, targetNodeUIPos.y - (newBgCenterPos.y - targetNodeUIPos.y))
            newBgCenterPos = pos2
        end

        local isHeightEnough2, heightFlowNum2 = CfUtils.IsPosHighInScreenRect(newBgCenterPos, bgRect.height * 0.5)
        local pos2 = newBgCenterPos
        if not isHeightEnough2 then
            if heightFlowNum < heightFlowNum2 then
                newBgCenterPos = Vector2.New(pos1.x, pos1.y + heightFlowNum)
            else
                newBgCenterPos = Vector2.New(pos2.x, pos2.y + heightFlowNum2)
            end
        end

        bgTargetPos = Vector2.New(newBgCenterPos.x - bgOffsetX, newBgCenterPos.y - bgOffsetY)
    end

    self.Bg.localPosition = Vector2.New(bgTargetPos.x, bgTargetPos.y)
end

--- 修改bg的锚点
---@param pivot any
function CommonTipsBoard:SetBgPivot(pivot)
    local rt = self.Bg.transform:GetComponent(typeof(RectTransform))
    rt.pivot = pivot
end

